111:   recuperarInscripcion(IdInscripcion: any) {
112:     return new Promise((resolve, reject) => {
113:       this.inscripcionService.get('inscripcion?query=Id:' + IdInscripcion)
114:         .subscribe((response: any) => {
115:           if (Object.keys(response[0]).length > 0) {
116:             resolve(response[0]);
117:           } else {
118:             this.popUpManager.showErrorToast(this.translate.instant('ERROR.'));
119:             this.infoFalla();
120:             reject(false);
121:           }
122:         },
123:           (error: any) => {
124:             console.error(error);
125:             this.infoFalla();
126:             this.popUpManager.showErrorToast(this.translate.instant('ERROR.' + error.status));
127:             reject(false);
128:           });
129:     });
130:   }
131: 
132:   recuperarEnfasis(idEnfasis: any) {
133:     return new Promise((resolve, reject) => {
134:       this.programaService.get('enfasis/' + idEnfasis)
135:         .subscribe((response: any) => {
136:           if (response.Status != "404") {
137:             resolve(response);
138:           } else {
139:             this.infoFalla();
140:             reject(false);
141:           }
142:         },
143:           (error: any) => {
144:             console.error(error);
145:             this.infoFalla();
146:             this.popUpManager.showErrorToast(this.translate.instant('ERROR.' + error.status));
147:             reject(false);
148:           });
149:     });
150:   }
151: 
152:   recuperarPeriodo(idPeriodo: any) {
153:     return new Promise((resolve, reject) => {
154:       this.parametrosService.get('periodo/' + idPeriodo)
155:         .subscribe((response: any) => {
156:           resolve(response.Data);
157:         },
158:           (error: any) => {
159:             console.error(error);
160:             this.infoFalla();
161:             this.popUpManager.showErrorToast(this.translate.instant('ERROR.' + error.status));
162:             reject(false);
163:           });
164:     });
165:   }
166: 
167:   addCargado(carga: number) {
168:     this.infoCarga.nCargado += carga;
169:     this.infoCarga.porcentaje = this.infoCarga.nCargado/this.infoCarga.nCargas;
170:     if (this.infoCarga.porcentaje >= 1) {
171:       this.infoCarga.status = "completed";
172:       let fechaRaw = new Date(new Date(this.inscripcion.FechaInscribe).getTime()+5*3600*1000);
173:       this.infoCarga.outInfo = {
174:         id: this.inscripcion_id,
175:         programa_id: this.programa_id,
176:         nombrePrograma: this.inscripcion.Programa,
177:         enfasis: this.inscripcion.Enfasis,
178:         fechaInsripcion: fechaRaw.toLocaleString('es-CO', { timeZone: 'America/Bogota' }),
179:         periodo: this.inscripcion.Periodo,
180:         idRecibo: this.inscripcion.idRecibo,
181:       }
182:     }
183:     this.estadoCarga.emit(this.infoCarga);
184:   }
185: 
186:   infoFalla() {
187:     this.infoCarga.status = "failed";
188:     this.estadoCarga.emit(this.infoCarga);
189:   }
190: }

